mapper.select:
select cell_key from roam_member_fog_cell
where member_id = #{memberId} and cell_prefix5 in
#{p}
order by cell_key
limit #{limit}

select cell_key from roam_member_fog_cell where member_id = #{memberId}
order by last_revealed_at desc, cell_key
limit #{limit}

mapper.delete:
delete from roam_member_fog_cell where last_revealed_at <= #{cutoff}
order by last_revealed_at
limit #{limit}
